  if(!state||!Array.isArray(state.lands)) state=freshState();
  const jakartaToday=dateAt(today());
  let route='dashboard', calMonth=new Date(jakartaToday.getFullYear(),jakartaToday.getMonth(),1), calView='month', calSelected=today(), calendarFilter={landId:'',status:''}, landTab='lands', reportFilters={from:'',to:'',landId:'',blockId:'',status:''}, searchText='';
  const PAGE_NAMES={dashboard:'Dashboard',calendar:'Kalender',today:'Tugas Hari Ini',lands:'Data Lahan',cycles:'Siklus Tanam',monitoring:'Monitoring Tanaman',care:'Perawatan',workers:'Tenaga Kerja',stock:'Stok',costs:'Biaya',harvest:'Panen',reports:'Laporan',templates:'Template Jadwal',settings:'Pengaturan'};
